  const SPLITLOG_HTML = "<div class=\"wrap\">\n    <!-- Widget-mode card: only visible when view='today' is collapsed -->\n    <div class=\"widget-host\" id=\"widget-host\" hidden></div>\n\n    <div class=\"app-header\">\n      <div class=\"home-divider\"><span>TODAY'S SESSION<span id=\"demo-badge-slot\"></span></span></div>\n      <button class=\"app-gear\" id=\"open-settings-sheet\" aria-label=\"Settings\" title=\"Settings\">\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <circle cx=\"12\" cy=\"12\" r=\"3\"/>\n          <path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z\"/>\n        </svg>\n        <span class=\"sync-dot local\" id=\"sync-dot\" aria-hidden=\"true\"></span>\n      </button>\n    </div>\n    <div id=\"demo-banner-slot\"></div>\n    <div id=\"split-section\"></div>\n\n    <input type=\"file\" id=\"data-import-input\" accept=\"application/json\" style=\"display:none;\" />\n  </div>\n\n  <!-- Wizard modal -->\n  <div class=\"modal\" id=\"edit-modal\">\n    <div class=\"modal-sheet\" id=\"modal-sheet\"></div>\n  </div>\n\n  <!-- Settings sheet (gear icon top-right opens this) -->\n  <div class=\"modal\" id=\"settings-modal\">\n    <div class=\"modal-sheet\" id=\"settings-sheet\">\n      <div class=\"modal-title\">Settings</div>\n      <div class=\"modal-sub\">Manage your data and customize your split.</div>\n      <!-- Sync section (only visible when not in DEMO_MODE; rendered by JS) -->\n      <div class=\"sync-section\" id=\"sync-section\" hidden></div>\n\n      <div class=\"settings-list\">\n        <button class=\"settings-row\" id=\"settings-customize\">\n          <span class=\"settings-row-label\">\n            Customize split\n            <span class=\"settings-row-sub\">Edit days, exercises &amp; weights</span>\n          </span>\n          <span class=\"settings-row-chev\">›</span>\n        </button>\n        <button class=\"settings-row\" id=\"settings-tailor\">\n          <span class=\"settings-row-label\">\n            Tailor starting weights\n            <span class=\"settings-row-sub\">Your bodyweight, level &amp; units</span>\n          </span>\n          <span class=\"settings-row-chev\">›</span>\n        </button>\n        <button class=\"settings-row\" id=\"settings-export\">\n          <span class=\"settings-row-label\">\n            Export data\n            <span class=\"settings-row-sub\">Download a JSON backup</span>\n          </span>\n          <span class=\"settings-row-chev\">↓</span>\n        </button>\n        <button class=\"settings-row\" id=\"settings-import\">\n          <span class=\"settings-row-label\">\n            Import data\n            <span class=\"settings-row-sub\">Restore from a backup file</span>\n          </span>\n          <span class=\"settings-row-chev\">↑</span>\n        </button>\n        <button class=\"settings-row danger\" id=\"settings-reset\">\n          <span class=\"settings-row-label\">\n            Reset all data\n            <span class=\"settings-row-sub\">Wipes your split, history &amp; profile</span>\n          </span>\n          <span class=\"settings-row-chev\">›</span>\n        </button>\n      </div>\n      <div class=\"settings-msg\" id=\"settings-msg\"></div>\n      <div class=\"settings-meta\">\n        SplitLog · <span id=\"settings-version\">v1.0</span><br>\n        Single-file workout tracker · data stays on this device\n      </div>\n      <button class=\"settings-close\" id=\"settings-close\">Close</button>\n    </div>\n  </div>\n\n  <!-- Tip / swap popover -->\n  <div class=\"popover-mask\" id=\"popover\">\n    <div class=\"popover-sheet\" id=\"popover-sheet\"></div>\n  </div>\n\n  <!-- Between-set rest timer (floats above content) -->\n  <div class=\"rest-timer\" id=\"rest-timer\" hidden>\n    <div class=\"rest-timer-label\" id=\"rest-timer-label\">Rest</div>\n    <div class=\"rest-timer-time\" id=\"rest-timer-time\">0:00</div>\n    <div class=\"rest-timer-bar\"><div class=\"rest-timer-fill\" id=\"rest-timer-fill\"></div></div>\n    <div class=\"rest-timer-actions\">\n      <button class=\"rest-timer-step\" id=\"rest-timer-sub\">− 15s</button>\n      <button class=\"rest-timer-step\" id=\"rest-timer-add\">+ 15s</button>\n      <button class=\"rest-timer-skip\" id=\"rest-timer-skip\">Skip</button>\n    </div>\n  </div>";

  let _mounted = false;

