    const PROFILE_KEY = NS + 'profile';
    function getProfile() {
      try { return JSON.parse(localStorage.getItem(PROFILE_KEY) || 'null'); } catch { return null; }
    }
    function saveProfile(p) {
      if (p) tryWrite(PROFILE_KEY, JSON.stringify(p));
      else  localStorage.removeItem(PROFILE_KEY);
    }

    // ── Setup-complete + data-version tracking ────────────────────────────
    function isSetupComplete() {
      return localStorage.getItem(SETUP_KEY) === 'true';
    }
    function maybeMarkSetupComplete() {
      const split = getSplit();
      const hasSplit = !!split && Array.isArray(split) && split.length > 0;
      const hasProfile = !!getProfile();
      if (hasSplit && hasProfile) tryWrite(SETUP_KEY, 'true');
    }
    function clearSetupComplete() { tryRemove(SETUP_KEY); }
    function initDataVersion() {
      if (!localStorage.getItem(DATA_VERSION_KEY)) {
        tryWrite(DATA_VERSION_KEY, String(CURRENT_DATA_VERSION));
      }
    }
    function tailorWeight(exId, profile) {
      if (!profile || !profile.weight) return null;
      const t = TAILOR_TABLE[exId];
      if (!t) return null;
      const gMap = t[profile.gender === 'f' ? 'f' : 'm'];
      const v = gMap[profile.level] || gMap.int;
      let w = 0;
      if (t.type === 'bw' || t.type === 'bwHalf') w = profile.weight * v;
      else                                        w = v; // 'add' or 'fixed'
      if (profile.age && profile.age > 35) {
        w *= Math.max(0.65, 1 - (profile.age - 35) * 0.005);
      }
      if (w <= 0) return 0;
      if (w < 5)  return Math.max(0, Math.round(w * 2) / 2);
      return Math.max(0, Math.round(w * 2 / 5) * 2.5);
    }
    function tailorEstimate(exId) {
      return tailorWeight(exId, getProfile());
    }

