    // ── Auto-detect category from day name ─────────────────────────────────
    // Tries to be lenient — covers most common ways people name training days
    // ("Lower", "Leg day", "Glutes + hams", "Delts", "Lats / Traps", etc.).
    // First match wins, so more specific patterns sit earlier in the chain.
    function detectCategory(name, type) {
      const n = (name || '').toLowerCase();
      if ((type || '').toUpperCase() === 'RECOVERY') return 'rest';
      if (/rest|recovery|off\s*day|deload/.test(n)) return 'rest';
      if (/upper/.test(n)) return 'upper';
      if (/lower/.test(n)) return 'lower';
      if (/full[\s-]?body|full body/.test(n)) return 'full';
      if (/push/.test(n)) return 'push';
      if (/pull/.test(n)) return 'pull';
      if (/legs?\b|quad|ham|glut|calf|calves|posterior chain/.test(n)) return 'legs';
      if (/chest|pec/.test(n)) return 'chest';
      if (/back\b|lat\b|lats\b|traps?\b/.test(n)) return 'back';
      if (/shoulder|delts?\b|ohp|press day/.test(n)) return 'shoulders';
      if (/arms?\b|bicep|tricep|gun day/.test(n)) return 'arms';
      if (/abs?\b|core|midline|six[\s-]?pack/.test(n)) return 'abs';
      return 'full'; // safe default — Full Body has a good catch-all exercise list
    }

